class Solution {
  public int minSwaps(int[] nums) {
    int n = nums.length;
    long[] keys = new long[n];
    for (int i = 0; i < n; i++) {
      int s = 0;
      for (int t = nums[i]; t > 0; t /= 10) s += t % 10;
      keys[i] = ((long) s * 2_000_000_000L + nums[i]) * 131072L + i;
    }
    long[] sorted = keys.clone();
    java.util.Arrays.sort(sorted);
    int[] target = new int[n];
    for (int r = 0; r < n; r++) target[(int) (sorted[r] % 131072L)] = r;
    boolean[] seen = new boolean[n];
    int cycles = 0;
    for (int i = 0; i < n; i++) {
      if (seen[i]) continue;
      cycles++;
      for (int j = i; !seen[j]; j = target[j]) seen[j] = true;
    }
    return n - cycles;
  }
}
